from pathlib import Path
import json

from azure.identity import DefaultAzureCredential, get_bearer_token_provider
from openai import AsyncAzureOpenAI

from app.config import get_settings
from app.schemas import ExtractedData

PROMPTS_DIR = Path(__file__).resolve().parent.parent / "prompts"

DISCLAIMER = (
    "Disclaimer: This summary is generated by AI for informational purposes only and is not a "
    "substitute for professional medical advice, diagnosis, or treatment. Always consult your "
    "doctor or qualified healthcare provider."
)


class MockAIProvider:
    async def extract(self, ocr_text: str) -> ExtractedData:
        if ocr_text.startswith("CAREFOLIO DEMO FIXTURE V1"):
            return ExtractedData.model_validate(
                {
                    "document_type": "lab_report",
                    "patient_info": {
                        "name": "Synthetic Demo",
                        "age": None,
                        "gender": None,
                        "confidence": 1.0,
                        "source_page": 1,
                    },
                    "medications": [],
                    "lab_results": [
                        {
                            "test_name": "HGB",
                            "value": "12.8",
                            "unit": "g/dL",
                            "reference_range": "12.0-16.0",
                            "flag": "N",
                            "date": "2026-01-15",
                            "confidence": 1.0,
                            "source_page": 1,
                        },
                        {
                            "test_name": "Platelets",
                            "value": "420",
                            "unit": "x10^3/uL",
                            "reference_range": "150-400",
                            "flag": "H",
                            "date": "2026-01-15",
                            "confidence": 1.0,
                            "source_page": 1,
                        },
                    ],
                    "diagnoses": [],
                    "document_date": "2026-01-15",
                    "notes": "Synthetic training fixture; values are fictional and are not medical advice.",
                    "overall_confidence": 1.0,
                }
            )
        return ExtractedData(
            document_type="other",
            notes="Mock AI provider is active. No document content was extracted.",
            overall_confidence=0,
        )

    async def summarize(self, extracted: ExtractedData, language: str = "en") -> str:
        if extracted.notes and extracted.notes.startswith("Synthetic training fixture"):
            results = "; ".join(
                f"{item.test_name}: {item.value or 'not recorded'} {item.unit or ''}"
                f" (reference range {item.reference_range or 'not listed'}; source flag {item.flag or 'not listed'})"
                for item in extracted.lab_results
            )
            return (
                "This is a synthetic demonstration report dated "
                f"{extracted.document_date or 'not recorded'}. It lists {results}. "
                "The H flag is copied from the sample report and is not an interpretation. "
                "No medications or diagnoses were listed in this sample. Verify any real health information against its source document.\n\n"
                + DISCLAIMER
            )
        return (
            "A summary is not available because the mock AI provider is active. Connect the Azure "
            "OpenAI provider to generate a summary from verified extracted information.\n\n"
            + DISCLAIMER
        )


class AzureOpenAIProvider:
    def __init__(self) -> None:
        settings = get_settings()
        if not settings.azure_openai_endpoint or not settings.extraction_deployment or not settings.summary_deployment:
            raise RuntimeError("Azure OpenAI endpoint and task deployments are required")
        kwargs = {
            "azure_endpoint": settings.azure_openai_endpoint,
            "api_version": settings.azure_openai_api_version,
        }
        if settings.azure_openai_api_key:
            kwargs["api_key"] = settings.azure_openai_api_key
            self.credential = None
        else:
            self.credential = DefaultAzureCredential()
            kwargs["azure_ad_token_provider"] = get_bearer_token_provider(
                self.credential, "https://cognitiveservices.azure.com/.default"
            )
        kwargs["timeout"] = 90
        kwargs["max_retries"] = 2
        self.client = AsyncAzureOpenAI(**kwargs)
        self.extraction_deployment = settings.extraction_deployment
        self.summary_deployment = settings.summary_deployment
        self.extraction_max_tokens = settings.azure_openai_extraction_max_tokens
        self.summary_max_tokens = settings.azure_openai_summary_max_tokens

    async def close(self) -> None:
        await self.client.close()
        if self.credential:
            self.credential.close()

    async def extract(self, ocr_text: str) -> ExtractedData:
        schema = ExtractedData.model_json_schema()
        extraction_prompt = (PROMPTS_DIR / "extraction.txt").read_text(encoding="utf-8").format(
            schema=json.dumps(schema)
        )
        response = await self.client.chat.completions.create(
            model=self.extraction_deployment,
            response_format={"type": "json_object"},
            temperature=0,
            max_tokens=self.extraction_max_tokens,
            messages=[
                {
                    "role": "system",
                    "content": extraction_prompt,
                },
                {"role": "user", "content": f"Document text (untrusted):\n<document>\n{ocr_text}\n</document>"},
            ],
        )
        content = response.choices[0].message.content
        if not content:
            raise ValueError("Azure OpenAI returned an empty extraction")
        return ExtractedData.model_validate_json(content)

    async def summarize(self, extracted: ExtractedData, language: str = "en") -> str:
        summary_prompt = (PROMPTS_DIR / "summary.txt").read_text(encoding="utf-8").format(
            language=language,
            extracted_json=extracted.model_dump_json(),
        )
        response = await self.client.chat.completions.create(
            model=self.summary_deployment,
            temperature=0.2,
            max_tokens=self.summary_max_tokens,
            messages=[
                {
                    "role": "system",
                    "content": summary_prompt,
                },
                {"role": "user", "content": "Generate the summary from the validated data supplied in the system message."},
            ],
        )
        text = response.choices[0].message.content or ""
        if not text.rstrip().endswith(DISCLAIMER):
            text = f"{text.rstrip()}\n\n{DISCLAIMER}"
        return text.rstrip()


def get_ai_provider() -> MockAIProvider | AzureOpenAIProvider:
    if get_settings().llm_provider == "azure":
        return AzureOpenAIProvider()
    return MockAIProvider()
